mapper.select:
SELECT B.*, PI.ItemDesc, CC.CustCpnId, CC.CustCpnDiscntAmt, PC.ProdCpnId, PC.ProdCpnDiscntAmt, PT.PointSaveAmt FROM shopion.tOrdBasket B LEFT OUTER JOIN shopion.tPrdProd P ON B.ProdCode = P.ProdCode LEFT OUTER JOIN shopion.tPrdProdItem PI ON B.ProdCode = PI.ProdCode AND B.ItemCode = PI.ItemCode LEFT OUTER JOIN shopion.tStrCustCpn CC ON B.CustCpnId = CC.CustCpnId LEFT OUTER JOIN shopion.tStrPoint PT ON B.ProdCode = PT.ProdCode LEFT OUTER JOIN shopion.tPrdProdDeliFee ODF ON B.DeliFeeId = ODF.DeliFeeId
AND CustId = #{pCustId}
AND SessonId = #{pSessonId}
AND B.DirectOrderYn = '0'
AND B.BasketNo IN #{item}
AND B.BasketNo = #{pBasketNo}
ORDER BY B.BasketNo DESC

SELECT B.*
FROM shopion.tPrdProd P
WHERE P.ProdCode = #{prodCode}

SELECT *
FROM shopion.tOrdBasket



            AND CustId = #{pCustId}


            AND SessonId = #{pSessonId}


    AND DirectOrderYn = '0'

ORDER BY BasketNo DESC

SELECT *
FROM shopion.tOrdBasket
WHERE ProdCode = #{prodCode}
AND ItemCode = #{itemCode}


        AND CustId = #{pCustId}


        AND SessonId = #{pSessonId}

mapper.update:
UPDATE shopion.tOrdBasket SET
    ProdQty = #{prodQty},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE BasketNo = #{basketNo}

UPDATE shopion.tOrdBasket SET
    CustId = #{custId},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE SessonId = #{sessonId}

UPDATE shopion.tOrdBasket SET
    MroYn = #{mroYn},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE BasketNo = #{basketNo}

